import datetime
import unittest
from decimal import Decimal

import pennywise
from pennywise import ParseError, balance, by_category, by_month, filter_entries, parse

D = datetime.date


class ParseTests(unittest.TestCase):
    def test_basic_entry(self):
        (e,) = parse("2024-03-02 Groceries -42.50 weekly shop\n")
        self.assertEqual(e.date, D(2024, 3, 2))
        self.assertEqual(e.category, "groceries")
        self.assertEqual(e.amount, Decimal("-42.50"))
        self.assertIsInstance(e.amount, Decimal)
        self.assertEqual(e.note, "weekly shop")

    def test_no_note_is_empty_string(self):
        (e,) = parse("2024-03-05 Rent -900")
        self.assertEqual(e.note, "")

    def test_file_order_kept(self):
        es = parse("2024-03-05 a 1\n2024-03-01 b 2\n2024-03-03 c 3")
        self.assertEqual([e.category for e in es], ["a", "b", "c"])

    def test_valid_amounts(self):
        for tok, want in [
            ("2500", "2500"),
            ("+2500", "2500"),
            ("2500.00", "2500.00"),
            ("12.5", "12.5"),
            ("-0.99", "-0.99"),
            ("12", "12"),
        ]:
            (e,) = parse("2024-01-01 x " + tok)
            self.assertEqual(e.amount, Decimal(want), tok)

    def test_invalid_amounts(self):
        for tok in ["12.505", "1,000.00", "abc", ".5", "12.", "1e3", "--1", "1.2.3"]:
            with self.assertRaises(ParseError, msg=tok):
                parse("2024-01-01 x " + tok)

    def test_invalid_dates(self):
        for tok in ["2024-02-30", "2024-13-01", "24-03-01", "2024-3-1", "2024/03/01"]:
            with self.assertRaises(ParseError, msg=tok):
                parse(tok + " x 1")

    def test_blank_and_comments_skipped(self):
        es = parse("# c\n\n   \n  # indented\n2024-01-01 x 1\n\t\n")
        self.assertEqual(len(es), 1)

    def test_empty_text(self):
        self.assertEqual(parse(""), [])

    def test_note_whitespace_preserved_and_trimmed(self):
        (e,) = parse("2024-01-01 x 1   hello   big \t world  \t")
        self.assertEqual(e.note, "hello   big \t world")

    def test_tab_separators(self):
        (e,) = parse("2024-01-01\tx\t\t5\tnote here")
        self.assertEqual((e.category, e.amount, e.note), ("x", Decimal(5), "note here"))

    def test_crlf(self):
        es = parse("2024-01-01 x 1 a\r\n2024-01-02 y 2\r\n")
        self.assertEqual([e.note for e in es], ["a", ""])

    def test_leading_whitespace_line(self):
        (e,) = parse("   2024-01-01 x 1  ")
        self.assertEqual(e.note, "")

    def test_too_few_fields(self):
        for text in ["2024-01-01", "2024-01-01 x"]:
            with self.assertRaises(ParseError):
                parse(text)

    def test_error_line_number_counts_physical_lines(self):
        text = "# c\n\n2024-01-01 x 1\n\n2024-02-30 x 1\n"
        with self.assertRaises(ParseError) as cm:
            parse(text)
        self.assertEqual(cm.exception.line, 5)
        self.assertIn("line 5", str(cm.exception))
        self.assertTrue(str(cm.exception).startswith("line 5: "))

    def test_error_is_value_error(self):
        self.assertTrue(issubclass(ParseError, ValueError))
        with self.assertRaises(ValueError):
            parse("bad")

    def test_error_message_example(self):
        with self.assertRaises(ParseError) as cm:
            parse("\n\n\n2024-01-01 x 12.505")
        self.assertEqual(str(cm.exception), "line 4: invalid amount '12.505'")

    def test_non_ascii_digits_rejected(self):
        with self.assertRaises(ParseError):
            parse("2024-01-01 x \u0661\u0662")

    def test_public_api(self):
        for name in ["Entry", "ParseError", "parse", "balance", "by_category",
                     "by_month", "filter_entries"]:
            self.assertTrue(hasattr(pennywise, name), name)


SAMPLE = """\
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop
2024-03-05 Rent -900
2024-04-01 Groceries -10
"""


class AggregationTests(unittest.TestCase):
    def setUp(self):
        self.entries = parse(SAMPLE)

    def test_balance(self):
        self.assertEqual(balance(self.entries), Decimal("1547.50"))
        self.assertEqual(balance([]), Decimal(0))
        self.assertIsInstance(balance([]), Decimal)

    def test_by_category(self):
        self.assertEqual(
            by_category(self.entries),
            {"salary": Decimal("2500"), "groceries": Decimal("-52.50"), "rent": Decimal("-900")},
        )

    def test_by_month(self):
        self.assertEqual(
            by_month(self.entries),
            {"2024-03": Decimal("1557.50"), "2024-04": Decimal("-10")},
        )

    def test_filter_none_keeps_all(self):
        self.assertEqual(filter_entries(self.entries), self.entries)

    def test_filter_category_case_insensitive(self):
        got = filter_entries(self.entries, category="GROCERIES")
        self.assertEqual([e.amount for e in got], [Decimal("-42.50"), Decimal("-10")])

    def test_filter_inclusive_bounds(self):
        got = filter_entries(self.entries, since=D(2024, 3, 2), until=D(2024, 3, 5))
        self.assertEqual([e.category for e in got], ["groceries", "rent"])

    def test_filter_order_kept(self):
        es = parse("2024-03-05 a 1\n2024-03-01 b 2\n2024-03-03 c 3")
        self.assertEqual(filter_entries(es, since=D(2024, 3, 1)), es)

    def test_filter_combined(self):
        got = filter_entries(self.entries, category="groceries", since=D(2024, 4, 1))
        self.assertEqual(len(got), 1)


if __name__ == "__main__":
    unittest.main()
