import contextlib
import io
import json
import os
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

from pennywise import cli

SAMPLE = """\
# household, March
2024-03-01 salary 2500.00 March pay
2024-03-02 groceries -42.50 weekly shop

2024-03-05 Rent -900
"""


def run(argv, stdin=None):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        if stdin is not None:
            with mock.patch.object(sys, "stdin", io.StringIO(stdin)):
                code = cli.main(argv)
        else:
            code = cli.main(argv)
    return code, out.getvalue(), err.getvalue()


class CliCase(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.path = os.path.join(self.tmp.name, "house.txt")
        self.write(SAMPLE)

    def write(self, text, path=None):
        with open(path or self.path, "w", encoding="utf-8", newline="") as fh:
            fh.write(text)

    def read_bytes(self):
        with open(self.path, "rb") as fh:
            return fh.read()


class BalanceTests(CliCase):
    def test_balance(self):
        self.assertEqual(run(["balance", self.path]), (0, "1557.50\n", ""))

    def test_balance_json(self):
        self.assertEqual(run(["balance", self.path, "--json"]), (0, '{"balance": "1557.50"}\n', ""))

    def test_balance_empty_and_negative_zero(self):
        self.write("")
        self.assertEqual(run(["balance", self.path])[1], "0.00\n")
        self.write("2024-01-01 a -0\n")
        self.assertEqual(run(["balance", self.path])[1], "0.00\n")

    def test_balance_stdin(self):
        self.assertEqual(run(["balance", "-"], stdin=SAMPLE), (0, "1557.50\n", ""))


class SummaryTests(CliCase):
    def test_default_by_category(self):
        self.assertEqual(
            run(["summary", self.path]),
            (0, "groceries  -42.50\nrent  -900.00\nsalary  2500.00\n", ""),
        )

    def test_by_month(self):
        self.write(SAMPLE + "2024-04-01 x 1\n")
        self.assertEqual(
            run(["summary", self.path, "--by", "month"]),
            (0, "2024-03  1557.50\n2024-04  1.00\n", ""),
        )

    def test_json_sorted(self):
        code, out, _ = run(["summary", self.path, "--json"])
        self.assertEqual(code, 0)
        self.assertEqual(out, '{"groceries": "-42.50", "rent": "-900.00", "salary": "2500.00"}\n')

    def test_stdin(self):
        self.assertEqual(run(["summary", "-"], stdin="2024-01-01 A 1\n")[1], "a  1.00\n")

    def test_bad_by(self):
        code, out, _ = run(["summary", self.path, "--by", "year"])
        self.assertEqual((code, out), (2, ""))


class ListTests(CliCase):
    def test_list_all(self):
        self.assertEqual(
            run(["list", self.path]),
            (0, "2024-03-01 salary 2500.00 March pay\n2024-03-02 groceries -42.50 weekly shop\n"
                "2024-03-05 rent -900.00\n", ""),
        )

    def test_filters(self):
        code, out, _ = run(["list", self.path, "--category", "GROCERIES"])
        self.assertEqual(out, "2024-03-02 groceries -42.50 weekly shop\n")
        out = run(["list", self.path, "--since", "2024-03-02", "--until", "2024-03-02"])[1]
        self.assertEqual(out, "2024-03-02 groceries -42.50 weekly shop\n")

    def test_sorted_and_stable(self):
        self.write("2024-03-05 b 1 first\n2024-03-01 z 2\n2024-03-05 a 3 second\n2024-03-05 c 4\n")
        out = run(["list", self.path])[1].splitlines()
        self.assertEqual(
            out,
            ["2024-03-01 z 2.00", "2024-03-05 b 1.00 first", "2024-03-05 a 3.00 second",
             "2024-03-05 c 4.00"],
        )

    def test_json(self):
        code, out, _ = run(["list", self.path, "--json", "--category", "rent"])
        self.assertEqual(
            json.loads(out),
            [{"date": "2024-03-05", "category": "rent", "amount": "-900.00", "note": ""}],
        )
        self.assertEqual(run(["list", self.path, "--json", "--category", "nope"])[1], "[]\n")

    def test_bad_dates_exit_2(self):
        for opt in ["--since", "--until"]:
            for val in ["2024-02-30", "yesterday", "24-03-01"]:
                code, out, err = run(["list", self.path, opt, val])
                self.assertEqual((code, out), (2, ""), (opt, val))
                self.assertTrue(err)

    def test_stdin(self):
        self.assertEqual(run(["list", "-"], stdin="2024-01-01 A 1 hi\n")[1], "2024-01-01 a 1.00 hi\n")


