        code, out, err = run(["add", self.path, "2024-03-07", "Groceries", "-12.3", "  corner  shop "])
        self.assertEqual((code, out, err), (0, "2024-03-07 groceries -12.30 corner  shop\n", ""))
        self.assertEqual(self.read_bytes(), (SAMPLE + "2024-03-07 groceries -12.30 corner  shop\n").encode())

